namespace {

using v8::FunctionTemplate;
using v8::Local;
using v8::Object;
using v8::String;
using v8::Value;


NAN_METHOD(Socket) {
    int fd;
    int type;

    assert(info.Length() == 0);

    type = SOCK_STREAM;
    type |= SOCK_NONBLOCK | SOCK_CLOEXEC;

    fd = socket(AF_UNIX, type, 0);
    if (fd == -1) {
        fd = -errno;
        goto out;
    }

